// =====================================================================
// Находим напоминания, у которых next_date <= сегодня и enabled=TRUE.
// Возвращаем по одному item на каждое срабатывающее напоминание —
// Telegram-нода затем отправит сообщение по каждому.
//
// Для recurring обновляем next_date по правилу:
//   once     → enabled=FALSE
//   daily    → next_date = today + 1
//   weekly   → next_date = today + 7
//   monthly  → next_date = today + ~30 (берём день того же месяца + 1мес)
//   yearly   → next_date = today + 365 (тот же день+месяц следующего года)
//   N (число)→ next_date = today + N
// last_sent всегда обновляется на today.
// =====================================================================

const raw = $('Тянем reminders CSV').item.json.data || $('Тянем reminders CSV').item.json || '';
const todayIso = $('Конфиг').item.json.today_iso;
const chatId = $('Конфиг').item.json.telegram_chat_id;

function parseCsv(text) {
  if (typeof text !== 'string') text = String(text);
  const lines = text.split(/\r?\n/).filter(Boolean);
  if (!lines.length) return [];
  const splitLine = (s) => s.match(/("([^"]|"")*"|[^,]*)(,|$)/g)
    .filter(Boolean)
    .map(v => v.replace(/,$/, '').replace(/^"|"$/g, '').replace(/""/g, '"').trim());
  const headers = splitLine(lines[0]).map(h => h.trim());
  return lines.slice(1).map(line => {
    const cells = splitLine(line);
    const obj = {};
    headers.forEach((h, i) => { obj[h] = (cells[i] ?? '').trim(); });
    return obj;
  });
}

function addDays(iso, days) {
  const d = new Date(iso + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}
function addMonths(iso, months) {
  const d = new Date(iso + 'T00:00:00Z');
  d.setUTCMonth(d.getUTCMonth() + months);
  return d.toISOString().slice(0, 10);
}

const rows = parseCsv(raw);
const results = [];

for (const row of rows) {
  const enabled = String(row.enabled || '').toUpperCase();
  const nextDate = (row.next_date || '').trim();
  const id = (row.reminder_id || '').trim();
  const title = (row.title || '').trim();
  const freq = (row.frequency || 'once').trim();

  if (!id || !title || !nextDate) continue;
  if (enabled !== 'TRUE') continue;
  if (nextDate > todayIso) continue;  // ещё не сегодня

  // Считаем новые поля для записи обратно.
  let newNextDate = nextDate;
  let newEnabled = 'TRUE';

  if (freq === 'once') {
    newEnabled = 'FALSE';
  } else if (freq === 'daily') {
    newNextDate = addDays(todayIso, 1);
  } else if (freq === 'weekly') {
    newNextDate = addDays(todayIso, 7);
  } else if (freq === 'monthly') {
    newNextDate = addMonths(todayIso, 1);
  } else if (freq === 'yearly') {
    newNextDate = addMonths(todayIso, 12);
  } else {
    const n = parseInt(freq, 10);
    if (isFinite(n) && n > 0) newNextDate = addDays(todayIso, n);
    else newEnabled = 'FALSE';  // непонятная frequency — деактивируем после отправки
  }

  const description = (row.description || '').trim();
  const text = description
    ? `🔔 *Напоминание:* ${title}\n\n${description}`
    : `🔔 *Напоминание:* ${title}`;

  results.push({
    json: {
      chat_id: chatId,
      reply_text: text,
      // Поля для apppendOrUpdate в Sheets — на верхнем уровне для autoMap:
      reminder_id: id,
      title: title,
      description: description,
      next_date: newNextDate,
      frequency: freq,
      enabled: newEnabled,
      last_sent: todayIso
    }
  });
}

return results;
